#!/usr/bin/env python3
"""
Post LLM evaluation as a PR review on GitHub.

This script reads the evaluation JSON generated by grade_submission.py
and posts it as a PR review with inline comments on the student's PR.

Environment variables:
    GITHUB_TOKEN: GitHub token for API access
    GITHUB_REPOSITORY: owner/repo (set by GitHub Actions)
    GITHUB_EVENT_PATH: Path to event payload
"""

import json
import os
import sys
from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import HTTPError


def get_pr_number(repo: str, token: str) -> int | None:
    """Get the most recent open PR number for the repository."""
    url = f"https://api.github.com/repos/{repo}/pulls?state=open&sort=created&direction=desc&per_page=1"
    req = Request(url, headers={
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json"
    })
    try:
        with urlopen(req) as response:
            pulls = json.loads(response.read())
            if pulls:
                return pulls[0]["number"]
    except HTTPError as e:
        print(f"ERROR fetching PRs: {e}", file=sys.stderr)
    return None


def format_review_body(evaluation: dict) -> str:
    """Format the evaluation as a readable PR review body."""
    lines = ["## 🤖 Avaliação Automatizada por LLM\n"]

    # Overall score
    total = evaluation.get("total_score", "N/A")
    total_max = evaluation.get("total_max_score", 10)
    lines.append(f"**Nota total: {total}/{total_max}**\n")

    # Criteria table
    criteria = evaluation.get("criteria", [])
    if criteria:
        lines.append("### Notas por Critério\n")
        lines.append("| Critério | Nota | Máximo |")
        lines.append("|----------|------|--------|")
        for c in criteria:
            name = c.get("criterion_name", c.get("criterion_id", "?"))
            score = c.get("score", "?")
            max_score = c.get("max_score", 10)
            lines.append(f"| {name} | {score} | {max_score} |")
        lines.append("")

    # Feedback
    feedback = evaluation.get("student_feedback", "")
    if feedback:
        lines.append("### Feedback\n")
        lines.append(feedback)
        lines.append("")

    # Feedback items
    items = evaluation.get("feedback_items", [])
    if items:
        lines.append("### Pontos de Atenção\n")
        for i, item in enumerate(items, 1):
            problem = item.get("problem", "")
            how_to_fix = item.get("how_to_fix", "")
            refs = ", ".join(item.get("evidence_refs", []))
            lines.append(f"**{i}.** {problem}")
            if how_to_fix:
                lines.append(f"   - 💡 *Como consertar:* {how_to_fix}")
            if refs:
                lines.append(f"   - 📍 *Referência:* `{refs}`")
            lines.append("")

    lines.append("---")
    lines.append("*Esta avaliação foi gerada automaticamente por LLM como apoio ao monitor. "
                 "A nota oficial é atribuída pelo monitor humano.*")

    return "\n".join(lines)


def post_review(repo: str, pr_number: int, body: str, token: str):
    """Post a review on the PR."""
    url = f"https://api.github.com/repos/{repo}/pulls/{pr_number}/reviews"
    data = json.dumps({
        "body": body,
        "event": "COMMENT"  # COMMENT, not APPROVE or REQUEST_CHANGES
    }).encode("utf-8")

    req = Request(url, data=data, method="POST", headers={
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json",
        "Content-Type": "application/json"
    })

    try:
        with urlopen(req) as response:
            result = json.loads(response.read())
            print(f"Review posted successfully: {result.get('html_url', '')}")
    except HTTPError as e:
        body_text = e.read().decode("utf-8", errors="replace")
        print(f"ERROR posting review: {e.code} - {body_text}", file=sys.stderr)
        sys.exit(1)


def main():
    token = os.environ.get("GITHUB_TOKEN", "")
    repo = os.environ.get("GITHUB_REPOSITORY", "")

    if not token:
        print("ERROR: GITHUB_TOKEN not set", file=sys.stderr)
        sys.exit(1)

    if not repo:
        print("ERROR: GITHUB_REPOSITORY not set", file=sys.stderr)
        sys.exit(1)

    # Read evaluation
    eval_path = Path("evaluation.json")
    if not eval_path.exists():
        print("ERROR: evaluation.json not found. Run grade_submission.py first.",
              file=sys.stderr)
        sys.exit(1)

    evaluation = json.loads(eval_path.read_text(encoding="utf-8"))

    # Find PR
    pr_number = get_pr_number(repo, token)
    if pr_number is None:
        print("WARNING: No open PR found. Skipping review post.",
              file=sys.stderr)
        return

    # Format and post
    body = format_review_body(evaluation)
    post_review(repo, pr_number, body, token)


if __name__ == "__main__":
    main()
